import { readFile, writeFile } from "node:fs/promises";
import { basename, dirname, join, resolve } from "node:path";
import { isNonEmptyString, parseFrontmatter } from "./frontmatter.js";
import { findMarkdownFiles, toBundlePath } from "./fs-walk.js";
import { RESERVED_FILENAMES } from "./spec.js";

export interface IndexEntry {
  title: string;
  href: string;
  description: string;
  type: string;
}

export interface DirectoryIndex {
  directory: string;
  entries: IndexEntry[];
  grouped: Map<string, IndexEntry[]>;
}

export interface IndexResult {
  bundlePath: string;
  directories: DirectoryIndex[];
  written: string[];
  preview: string[];
}

export interface IndexOptions {
  write?: boolean;
}

/**
 * Generate index.md content for each directory that contains concept .md files,
 * grouping entries by frontmatter `type`.
 */
export async function indexBundle(
  bundlePath: string,
  options: IndexOptions = {},
): Promise<IndexResult> {
  const root = resolve(bundlePath);
  const markdownFiles = await findMarkdownFiles(root);
  const byDir = new Map<string, string[]>();

  for (const file of markdownFiles) {
    const name = basename(file);
    if (RESERVED_FILENAMES.has(name)) continue;
    const dir = dirname(file);
    const list = byDir.get(dir) ?? [];
    list.push(file);
    byDir.set(dir, list);
  }

  // Also include root even if only reserved files (empty concepts)
  if (!byDir.has(root)) {
    const rootHasMd = markdownFiles.some((f) => dirname(f) === root);
    if (rootHasMd || true) {
      // always allow root index generation when bundle exists
    }
  }

  const directories: DirectoryIndex[] = [];
  const written: string[] = [];
  const preview: string[] = [];

  // Ensure we process every directory that has concept files, plus root
  const dirs = new Set(byDir.keys());
  dirs.add(root);

  // Include intermediate dirs that only have subdirs? Skip — only dirs with concepts or root
  for (const dir of [...dirs].sort()) {
    const files = byDir.get(dir) ?? [];
    const entries: IndexEntry[] = [];

    for (const file of files.sort()) {
      const content = await readFile(file, "utf8");
      const parsed = parseFrontmatter(content);
      const relName = basename(file);
      let title = stemTitle(relName);
      let description = "";
      let type = "untagged";

      if (parsed.ok && parsed.hasFrontmatter) {
        if (isNonEmptyString(parsed.data.title)) title = parsed.data.title.trim();
        if (isNonEmptyString(parsed.data.description)) {
          description = parsed.data.description.trim();
        }
        if (isNonEmptyString(parsed.data.type)) type = parsed.data.type.trim();
      }

      entries.push({
        title,
        href: relName,
        description: description || `See ${relName}`,
        type,
      });
    }

    const grouped = new Map<string, IndexEntry[]>();
    for (const entry of entries) {
      const list = grouped.get(entry.type) ?? [];
      list.push(entry);
      grouped.set(entry.type, list);
    }

    const dirRel = dir === root ? "." : toBundlePath(root, dir);
    directories.push({ directory: dirRel, entries, grouped });

    if (entries.length === 0 && dir !== root) continue;

    const markdown = renderIndex(dirRel === "." ? basename(root) : basename(dir), grouped);
    const indexPath = join(dir, "index.md");
    preview.push(`--- ${dirRel}/index.md ---\n${markdown}`);

    if (options.write) {
      await writeFile(indexPath, markdown, "utf8");
      written.push(
        dir === root ? "index.md" : `${toBundlePath(root, dir)}/index.md`,
      );
    }
  }

  return { bundlePath: root, directories, written, preview };
}

function renderIndex(title: string, grouped: Map<string, IndexEntry[]>): string {
  const lines: string[] = [`# ${title}`, ""];

  const types = [...grouped.keys()].sort((a, b) => a.localeCompare(b));
  if (types.length === 0) {
    lines.push("No concept documents in this directory yet.", "");
    return lines.join("\n");
  }

  for (const type of types) {
    lines.push(`## ${type}`, "");
    for (const entry of grouped.get(type) ?? []) {
      lines.push(`* [${entry.title}](${entry.href}) - ${entry.description}`);
    }
    lines.push("");
  }

  return lines.join("\n");
}

function stemTitle(filename: string): string {
  const stem = filename.replace(/\.md$/i, "");
  return stem
    .replace(/[-_]+/g, " ")
    .replace(/\b\w/g, (c) => c.toUpperCase());
}

export function formatIndexResult(result: IndexResult, write: boolean): string {
  if (write) {
    if (result.written.length === 0) {
      return `No index.md files written under ${result.bundlePath}.`;
    }
    return `Wrote ${result.written.length} index.md file(s):\n${result.written.map((w) => `  ${w}`).join("\n")}`;
  }
  return result.preview.join("\n\n") || "No concept documents found.";
}
